public static class ConnectionsLiveTest {
    static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool yes,string why){if(!yes)throw new Exception("Live Connections: "+why);}
    static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
    static T Find<T>(Window w,string name)where T:FrameworkElement{return Walk(w).OfType<T>().Single(e=>e.Name==name);}
    static void Unit(string directory){
        string stamp="2026-10-13T18:00:00.0000000Z";string record=stamp+" stage=connected account=2 conversation=account:2 expected_peer="+new string('a',64)+" current_peer="+new string('a',64)+" candidate=example.invalid:7443 source=Relay route=relay-only result=Authenticated winner";
        var input=new ConnectionsLiveInput{Profile="Fixture",Context="generation:1",DiscoveryConnected=true,ConnectionText="TCP/TLS state: Ready\npassword=not-public-a token=not-public-b\nauthorization=Bearer not-public-c",RetainedLog=record+"\n"+record.Replace("18:00:00","17:59:59"),Routes=new[]{new ConnectionsRouteObservation{Connected=true,WinnerId=41,Epoch=9,Revision=3,Peer=new string('a',64),Target="Contact",Conversation="account:2",Selected=true,Route="relay-only",Source="Server relay",Candidate="example.invalid:7443"}}};
        var provider=new ExistingConnectionsProvider(()=>input);var current=provider.Read();Check(!current.Sample&&current.Sessions.Length==1&&!current.Sessions[0].StartKnown&&current.Sessions[0].Duration==null,"current winner, not invented history/time");Check(current.Sessions[0].Id.Contains("epoch:9/connection:41"),"native scoped ID");Check(current.Events.Length==2&&current.Events[0].TimestampUtc<current.Events[1].TimestampUtc&&current.Events.All(e=>e.SessionId=="Not retained"&&e.AttemptId=="Not retained"),"retained ordering and missing native IDs");Check(ConnectionPreviewQuery.Filter(current,"All","All",current.Sessions[0].Id).Length==0,"no invented native event correlation");Check(ConnectionPreviewQuery.Filter(current,"All","All",current.Events[0].CorrelationId).Length==2,"logical scope filter");
        string exported=ConnectionPreviewQuery.Export(current);Check(!exported.Contains("not-public-")&&!exported.Contains("[SAMPLE]"),"real export credential redaction and no samples");Check(ConnectionsSafeText.Clean("-----BEGIN PRIVATE KEY-----\nnot-public-pem\n-----END PRIVATE KEY-----").IndexOf("not-public-pem",StringComparison.Ordinal)<0,"PEM redaction");Check(!ConnectionsSafeText.Clean("sessionToken=xsecret; turn_uri=turnsecret; ICE_pwd=icesecret").Contains("secret"),"mixed inline credentials");
        input.Routes[0].Connected=false;input.Routes[0].AttemptId=42;input.Routes[0].Transport="Waiting to retry";current=provider.Read();Check(current.Sessions[0].Id.Contains("attempt:42")&&current.Overview[2].Metrics[0].Value=="0","winner retired, latest attempt not connected");input.Routes=new ConnectionsRouteObservation[0];input.DiscoveryConnected=false;current=provider.Read();Check(current.Sessions.Length==0&&current.Events.Length==2,"disconnected does not manufacture retained sessions");
        var shared=new ConnectionsRouteObservation{Peer="shared-peer",Connected=true,WinnerId=9,Epoch=3,Route="relay-only",Target="Canonical"};input.Routes=new[]{shared,shared};Check(provider.Read().Sessions.Length==1&&provider.Read().Overview[2].Metrics[0].Value=="1","no duplicate native owner counts");input.SelectedSessionId="unrelated-old-scope";Check(provider.Read().Network[0].Metrics[0].Value=="No active session","never borrow another selected scope route");input.SelectedSessionId="";input.Routes=new ConnectionsRouteObservation[0];
        var retention=new DiagnosticsRetentionStore(Path.Combine(directory,"retained-projection"));retention.AddFailure(new FailureSnapshot{Id="retained-failure",OperationType="Connection",OperationId="41",TimestampUtc=stamp,Reason="identity failure password=badsecret",Stage="TLS verification",Diagnostics=new DiagnosticsSnapshot{Sections=new List<DiagnosticsSection>{new DiagnosticsSection{Name="Connection",Details="Conversation ID: account:2\nAccount ID: 2"}}}});input.Failures=retention.Failures().ToArray();var paths=Directory.GetFiles(Path.Combine(directory,"retained-projection"),"*",SearchOption.AllDirectories);var contents=paths.Select(File.ReadAllText).ToArray();for(int i=0;i<10;i++)current=provider.Read();Check(paths.Select(File.ReadAllText).SequenceEqual(contents),"projection writes no retention");Check(current.Failures.Length==1&&current.Failures[0].Id=="retained-failure"&&current.Failures[0].Recovery.Contains("Not retained")&&!current.Failures[0].Reason.Contains("badsecret")&&current.Failures[0].Target.Contains("not retained")&&current.Failures[0].Extra.Contains("account:2"),"frozen failure boundaries; selected context is not failed-peer proof");
    }
    static void Native(string directory){
        using(var left=new CoreAdapter())using(var right=new CoreAdapter()){
            string a="",b="";ulong la=0,ra=0;bool received=false;var tracker=new ConnectionAttemptTracker();var conversation=new ConversationModel{AccountId=72,ConversationId="account:72",AccountName="Isolated TLS peer",Contact=new ContactData()};var log=new ConnectionDiagnosticLog(Path.Combine(directory,"native-left"));
            left.Start(Path.Combine(directory,"native-left"),0,"Diagnostics left");right.Start(Path.Combine(directory,"native-right"),0,"Diagnostics right");
            Action poll=()=>{foreach(var e in left.Poll()??new CoreEvent[0]){if(e.kind==0)a=e.peer;if(e.kind==18)la=(ulong)e.attempt;if(e.kind==2)Check(left.PinInitialAuthenticatedFriendIdentity(e.peer,(ulong)e.attempt,1),"left authenticated initial identity pin");if(e.kind==3||e.kind==4||e.kind==14||e.kind==16||e.kind==17){tracker.Update(e,conversation,e.kind==3?"Ready":null);if(e.kind==3||e.kind==4||e.kind==14||e.kind==16)log.Record(e.kind==3?"connected":e.kind==4?"disconnected":e.kind==14?"connect":"connection-lifecycle",72,conversation.ConversationId,e.expected,e.peer,e.candidate,e.source,e.route,e.text);}}foreach(var e in right.Poll()??new CoreEvent[0]){if(e.kind==0)b=e.peer;if(e.kind==18)ra=(ulong)e.attempt;if(e.kind==2)Check(right.PinInitialAuthenticatedFriendIdentity(e.peer,(ulong)e.attempt,1),"right authenticated initial identity pin");if(e.kind==5)received=true;}};
            Action pump=()=>{var bytes=new byte[65536];if(la>0&&ra>0){for(int i=0;i<8;i++){int n=left.TakeRelayOutput(la,bytes,0);if(n<=0)break;Check(right.RelayReceive(ra,bytes,n),"right TLS bytes");}for(int i=0;i<8;i++){int n=right.TakeRelayOutput(ra,bytes,0);if(n<=0)break;Check(left.RelayReceive(la,bytes,n),"left TLS bytes");}}poll();};
            Action<Func<bool>,string> wait=(condition,why)=>{var until=DateTime.UtcNow.AddSeconds(20);while(DateTime.UtcNow<until){pump();if(condition())return;Thread.Sleep(5);}throw new Exception(why);};wait(()=>a.Length==64&&b.Length==64,"native ready identities");conversation.Contact.peer=b;
            Check(left.SetAuthenticatedFriends(71,1,new[]{new FriendConversationBinding{AccountId=72,CurrentPeerId=b,KnownPeerIds=new List<string>{b},ActiveFriend=true}})&&right.SetAuthenticatedFriends(72,1,new[]{new FriendConversationBinding{AccountId=71,CurrentPeerId=a,KnownPeerIds=new List<string>{a},ActiveFriend=true}}),"fixture authenticated friend bindings");left.SetNetworkContext(1,"diagnostics-fixture");right.SetNetworkContext(1,"diagnostics-fixture");left.UpdateCandidates(b,"",0,"",0,true,1,true);right.UpdateCandidates(a,"",0,"",0,true,1,true);wait(()=>la>0&&ra>0,"native relay attempts");Check(left.RelayReady(la,String.CompareOrdinal(a,b)>0)&&right.RelayReady(ra,String.CompareOrdinal(b,a)>0),"native relay binding");wait(()=>tracker.For(conversation).HasLiveSession,"native mutual TLS winner");
            var source=new ExistingConnectionsProvider(()=>{var d=tracker.For(conversation);return new ConnectionsLiveInput{Profile="Native fixture",Context="native-fixture",RetainedLog=log.Read(),Routes=new[]{new ConnectionsRouteObservation{Peer=b,Target=conversation.Name,Conversation=conversation.ConversationId,Connected=d.HasLiveSession,WinnerId=d.LiveConnectionId,AttemptId=d.AttemptId,Epoch=d.SessionEpoch,Revision=d.SessionRevision,Selected=true,Route=d.LiveRoute,Source=d.LiveSource,Candidate=d.LiveCandidate,Transport=d.TransportState,Trust=d.TrustState}}};});string before=log.Read();for(int i=0;i<10;i++){var state=source.Read();Check(state.Sessions.Length==1&&state.Overview[2].Metrics[0].Value=="1","real native winner projects");}Check(log.Read()==before,"opening/read does not create source events");Check(left.Send(b,"Isolated diagnostics continuity fixture"),"messaging accepted after diagnostics reads");wait(()=>received,"messaging delivered with diagnostics projection");
            left.RelayClosed(la,"fixture disconnect");wait(()=>!tracker.For(conversation).HasLiveSession,"native disconnect observed");Check(source.Read().Overview[2].Metrics[0].Value=="0","native disconnected state projects without historical fabrication");
        }Console.WriteLine("PASS: actual packaged native mutual-TLS relay binding -> managed tracker -> Connections projection; messaging continues; disconnect and no diagnostic writes. Host fixture, not Pi.");
    }
    public static async Task Run(DesktopApplication desktop,string directory){
        Unit(directory);Native(directory);typeof(DesktopApplication).GetField("connectionsDeveloperPreview",Flags).SetValue(desktop,false);var open=typeof(DesktopApplication).GetMethod("OpenContextDiagnostics",Flags);open.Invoke(desktop,new object[]{DiagnosticSection.Connections,""});var window=(Window)typeof(DesktopApplication).GetField("groupDiagnosticWindow",Flags).GetValue(desktop);var tabs=(TabControl)typeof(DesktopApplication).GetField("groupDiagnosticTabs",Flags).GetValue(desktop);window.UpdateLayout();Check(((ComboBox)typeof(DesktopApplication).GetField("connectionPreviewExamples",Flags).GetValue(desktop)).Visibility==Visibility.Collapsed,"normal UI has no sample selector");Check(((ConnectionPreviewSnapshot)typeof(DesktopApplication).GetField("connectionPreview",Flags).GetValue(desktop)).Sample==false,"normal real mode");
        tabs.SelectedIndex=5;window.UpdateLayout();var search=Find<TextBox>(window,"ConnectionLogSearch");search.Text="winning";var prior=search;await Task.Delay(1300);window.UpdateLayout();Check(Object.ReferenceEquals(prior,Find<TextBox>(window,"ConnectionLogSearch"))&&search.Text=="winning","live refresh preserves controls/search");Check(!((string)typeof(DesktopApplication).GetMethod("CurrentDiagnosticExport",Flags).Invoke(desktop,null)).StartsWith("SAMPLE"),"normal export real");
        var generation=typeof(DesktopApplication).GetField("authenticatedFriendSnapshotGeneration",Flags);ulong original=(ulong)generation.GetValue(desktop);generation.SetValue(desktop,original+1);await Task.Delay(1300);window.UpdateLayout();Check(!Object.ReferenceEquals(prior,Find<TextBox>(window,"ConnectionLogSearch"))&&Find<TextBox>(window,"ConnectionLogSearch").Text=="","context change discards old filters/controls");generation.SetValue(desktop,original);window.Close();Console.WriteLine("PASS: current/retained boundaries, redaction, ordering/filtering, developer isolation, read-only refresh and original diagnostics retained.");
    }
}
